// ── Small helpers ────────────────────────────────────────────────────────────

function showEl(id, visible) {
  const el = document.getElementById(id);
  if (el) el.hidden = !visible;
}

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function initFieldTips(root) {
  (root || document).querySelectorAll('.rm-tip-label').forEach(label => {
    if (label.dataset.tipInit) return;
    label.dataset.tipInit = '1';
    const icon = label.querySelector('.rm-tip-icon');
    if (!icon) return;
    icon.addEventListener('click', e => {
      e.preventDefault();
      e.stopPropagation();
      const open = label.classList.contains('rm-tip-open');
      document.querySelectorAll('.rm-tip-label.rm-tip-open').forEach(l => l.classList.remove('rm-tip-open'));
      if (!open) label.classList.add('rm-tip-open');
    });
  });
}

function fmtDate(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}.${mm}.${d.getFullYear()}`;
}

function fmtDateTime(value) {
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const hh = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  return `${dd}.${mm}.${d.getFullYear()} · ${hh}:${min}`;
}

function fmtD(iso) {
  if (!iso) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
    const [y, m, d] = iso.split('-');
    return `${d}.${m}.${y}`;
  }
  return iso;
}

function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function personColor(name) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = name.charCodeAt(i) + ((h << 5) - h);
  h = Math.abs(h) % 360;
  return { bg: `hsl(${h}, 28%, 88%)`, tx: `hsl(${h}, 32%, 32%)` };
}

function chip(name) {
  const c = personColor(name);
  return `<span class="person-chip" style="color:${c.tx}">${esc(name)}</span>`;
}

// 0 = unbewertet (statt frueher 1, das unbewertete Risiken als "Low" auswies).
function riskScore(likelihood, impact) {
  return (Number(likelihood) || 0) * (Number(impact) || 0);
}

function riskLevel(score) {
  if (score >= 16) return 'critical';
  if (score >= 10) return 'high';
  if (score >= 5) return 'medium';
  return 'low';
}

function riskLevelLabel(level) {
  return { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low' }[level] || level;
}

function riskStatusLabel(s) {
  return { open: 'Open', mitigating: 'Mitigating', monitoring: 'Monitoring', accepted: 'Accepted', closed: 'Closed' }[s] || s;
}

function strategyLabel(s) {
  return { mitigate: 'Mitigate', transfer: 'Transfer', accept: 'Accept', avoid: 'Avoid' }[s] || s;
}

