function canEdit() {
  return register && (register.role === 'owner' || register.role === 'editor');
}

function isOwner() {
  return register && register.role === 'owner';
}

function canCreateRegisters() {
  return myProfile?.can_create_registers !== false;
}

function areaByUuid(id) {
  return areas.find(a => a.id === id) || null;
}

function areaKey(a) {
  return a.code || a.id;
}

function nameFromEmail(email) {
  return email ? email.split('@')[0] : '';
}

function userName(userId) {
  if (!userId) return '';
  const p = profiles.get(userId);
  if (!p) return '';
  return p.display_name || nameFromEmail(p.email);
}

function currentUserName() {
  const metaName = session?.user?.user_metadata?.display_name;
  return userName(session?.user?.id) || metaName || nameFromEmail(session?.user?.email);
}

function risksOfArea(areaUuid) {
  return risks
    .filter(r => r.area_id === areaUuid)
    .sort((a, b) => (a.created_at || '').localeCompare(b.created_at || ''));
}

/** Stable display IDs like RSK-A01-01, numbered by creation order per area. */
function buildRiskLabels() {
  const labels = new Map();
  areas.forEach(a => {
    risksOfArea(a.id).forEach((r, idx) => {
      labels.set(r.id, `RSK-${areaKey(a)}-${String(idx + 1).padStart(2, '0')}`);
    });
  });
  risks.filter(r => !r.area_id || !areaByUuid(r.area_id)).forEach((r, idx) => {
    labels.set(r.id, `RSK-${String(idx + 1).padStart(2, '0')}`);
  });
  return labels;
}

function allRisksFlat() {
  const labels = buildRiskLabels();
  const today = todayISO();
  const out = [];
  const decorate = (r, area) => {
    const rl = r.residual_likelihood || 0;
    const ri = r.residual_impact || 0;
    const reviewDue = r.review_due || '';
    const status = r.status || 'open';
    const isOverdueReview = !!(reviewDue && reviewDue < today && status !== 'closed');
    return {
      uuid: r.id,
      id: labels.get(r.id) || r.id.slice(0, 8),
      areaUuid: area ? area.id : null,
      areaId: area ? areaKey(area) : '',
      areaTitle: area ? area.title : 'No area',
      title: r.title || '',
      description: r.description || '',
      cause: r.cause || '',
      consequence: r.consequence || '',
      likelihood: r.likelihood || 0,
      impact: r.impact || 0,
      strategy: r.strategy || 'mitigate',
      owner: r.owner || '',
      status,
      mitigation: r.mitigation || '',
      mitigationOwner: r.mitigation_owner || '',
      mitigationDue: r.mitigation_due || '',
      contingency: r.contingency || '',
      triggers: r.triggers || '',
      residualLikelihood: rl,
      residualImpact: ri,
      residualScore: (rl && ri) ? rl * ri : null,
      reviewDue,
      isOverdueReview,
      recordedAt: r.recorded_at || '',
      recordedBy: r.recorded_by_name || userName(r.recorded_by),
    };
  };
  areas.forEach(a => {
    risksOfArea(a.id).forEach(r => out.push(decorate(r, a)));
  });
  risks.filter(r => !r.area_id || !areaByUuid(r.area_id)).forEach(r => out.push(decorate(r, null)));
  return out;
}

// Nur Register-Mitglieder kommen als Owner/Recorded-by in Frage.
function memberNames() {
  const set = new Set();
  members.forEach(m => {
    const n = userName(m.user_id);
    if (n) set.add(n);
  });
  const me = currentUserName();
  if (me) set.add(me);
  return [...set].sort((a, b) => a.localeCompare(b));
}

// Select mit Mitgliedernamen fuellen; ein bestehender Freitext-Wert aus alten
// Risiken bleibt als zusaetzliche Option erhalten.
function fillPersonSelect(id, value, allowEmpty) {
  const el = document.getElementById(id);
  if (!el) return;
  const names = memberNames();
  const v = (value || '').trim();
  if (v && !names.includes(v)) names.push(v);
  el.innerHTML = (allowEmpty ? '<option value=""></option>' : '') +
    names.map(n => `<option value="${esc(n)}">${esc(n)}</option>`).join('');
  el.value = v || (allowEmpty ? '' : (names[0] || ''));
}

function lastUpdateText() {
  let latest = register?.updated_at || '';
  [...areas, ...risks].forEach(row => {
    if (row.updated_at && row.updated_at > latest) latest = row.updated_at;
  });
  return latest ? fmtDateTime(latest) : '';
}

