function openRiskModal(areaUuid, riskUuid) {
  fillRiskScaleSelects();
  if (!areas.length) {
    alert('Create an area first. Risks are grouped by area.');
    openAreaModal(null);
    return;
  }
  editRiskUuid = riskUuid || null;
  const editing = !!editRiskUuid;

  document.getElementById('riskModalTitle').textContent = editing ? 'Edit risk' : 'Add risk';
  document.getElementById('riskSaveBtn').textContent = editing ? 'Save changes' : 'Add risk';
  document.getElementById('riskSaveBtn').hidden = !canEdit();
  document.getElementById('btnDeleteRisk').hidden = !editing || !canEdit();

  renderAreaSelectOptions(areaUuid || areas[0].id);

  if (editing) {
    const r = risks.find(x => x.id === editRiskUuid);
    if (!r) { closeRiskModal(); return; }
    document.getElementById('riskArea').value = r.area_id || areas[0].id;
    document.getElementById('riskTitle').value = r.title || '';
    document.getElementById('riskDesc').value = r.description || '';
    document.getElementById('riskCause').value = r.cause || '';
    document.getElementById('riskConsequence').value = r.consequence || '';
    document.getElementById('riskLikelihood').value = String(r.likelihood || 3);
    document.getElementById('riskImpact').value = String(r.impact || 3);
    document.getElementById('riskStrategy').value = r.strategy || 'mitigate';
    document.getElementById('riskMitigation').value = r.mitigation || '';
    fillPersonSelect('riskMitOwner', r.mitigation_owner || '', true);
    document.getElementById('riskMitDue').value = /^\d{4}-\d{2}-\d{2}$/.test(r.mitigation_due || '') ? r.mitigation_due : '';
    document.getElementById('riskContingency').value = r.contingency || '';
    document.getElementById('riskTriggers').value = r.triggers || '';
    fillPersonSelect('riskOwner', r.owner || '', true);
    document.getElementById('riskStatus').value = r.status || 'open';
    document.getElementById('riskResidualL').value = r.residual_likelihood ? String(r.residual_likelihood) : '';
    document.getElementById('riskResidualI').value = r.residual_impact ? String(r.residual_impact) : '';
    document.getElementById('riskReviewDue').value = /^\d{4}-\d{2}-\d{2}$/.test(r.review_due || '') ? r.review_due : '';
    document.getElementById('riskRecordedAt').value = /^\d{4}-\d{2}-\d{2}$/.test(r.recorded_at || '') ? r.recorded_at : todayISO();
    fillPersonSelect('riskRecordedBy', r.recorded_by_name || userName(r.recorded_by) || currentUserName(), false);
  } else {
    clearRiskForm();
    if (areaUuid) document.getElementById('riskArea').value = areaUuid;
  }
  updateRiskPreview();
  syncScaleButtons();
  updateSectionCounts(false);
  updateRecordedLine();
  const recordedEdit = document.getElementById('riskRecordedEdit');
  if (recordedEdit) recordedEdit.hidden = true;
  initFieldTips(document.getElementById('riskModalBg'));
  document.getElementById('riskModalBg').classList.add('open');
  document.getElementById('riskTitle').focus();
}

function closeRiskModal() {
  document.getElementById('riskModalBg').classList.remove('open');
  editRiskUuid = null;
}

async function saveRisk() {
  if (!register || !canEdit()) return;
  const data = readRiskForm();
  if (!data.area_id) { alert('Select an area.'); return; }
  if (!data.title) { alert('Risk title is required.'); return; }
  if (!data.description) { alert('Risk event description is required.'); return; }
  if (!data.likelihood || !data.impact) { alert('Likelihood and impact are required.'); return; }

  const btn = document.getElementById('riskSaveBtn');
  if (btn) btn.disabled = true;
  try {
    if (editRiskUuid) {
      const r = risks.find(x => x.id === editRiskUuid);
      if (!r) { closeRiskModal(); return; }
      Object.assign(r, data);
      closeRiskModal();
      refreshAll();
      const row = await updateRisk(r.id, data);
      // Nach dem await per ID nachschlagen — Realtime kann das Objekt im
      // Array inzwischen ersetzt haben, die alte Referenz zeigt dann ins Leere.
      const cur = risks.find(x => x.id === row.id);
      if (cur) Object.assign(cur, row);
    } else {
      closeRiskModal();
      const row = await createRisk(register.id, data);
      if (!risks.some(x => x.id === row.id)) risks.push(row);
      if (row.recorded_by && !profiles.has(row.recorded_by)) await refreshProfiles();
    }
    document.getElementById('lastUpdate').textContent = lastUpdateText();
    refreshAll();
    setSyncStatus('ok', `Saved · ${risks.length} risk(s)`);
  } catch (e) {
    setSyncStatus('error', 'Could not save risk');
    alert(e.message || 'Could not save risk');
    await loadActiveRegister();
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function removeRisk(uuid) {
  const before = risks;
  risks = risks.filter(r => r.id !== uuid);
  refreshAll();
  try {
    await deleteRisk(uuid);
    setSyncStatus('ok', `Deleted · ${risks.length} risk(s)`);
  } catch (e) {
    risks = before;
    refreshAll();
    setSyncStatus('error', 'Could not delete risk');
    alert(e.message || 'Could not delete risk');
  }
}

async function deleteCurrentRisk() {
  if (!editRiskUuid || !canEdit()) return;
  if (!confirm('Delete this risk?')) return;
  const uuid = editRiskUuid;
  closeRiskModal();
  await removeRisk(uuid);
}

