// Verlauf lebt pro Register nur im Speicher; der Server ist zustandslos.

let botHistory = [];
let botBusy = false;
let botRegisterId = null;

// Reset nur bei echtem Registerwechsel — nicht bei jedem Meta-Update.
function resetBot() {
  if (register?.id === botRegisterId) return;
  botRegisterId = register?.id || null;
  botHistory = [];
  const msgs = document.getElementById('rmBotMsgs');
  if (msgs) msgs.innerHTML = '';
  const reg = document.getElementById('rmBotRegister');
  if (reg) reg.textContent = register?.title || '';
}

function toggleBotPanel() {
  const panel = document.getElementById('rmBotPanel');
  if (!panel) return;
  panel.hidden = !panel.hidden;
  document.getElementById('botToggleBtn')?.classList.toggle('open', !panel.hidden);
  if (!panel.hidden) {
    const reg = document.getElementById('rmBotRegister');
    if (reg) reg.textContent = register?.title || '';
    const msgs = document.getElementById('rmBotMsgs');
    if (msgs && !msgs.childElementCount) {
      appendBotMsg('bot', "Hi, I'm Cassandra, the risk coach. In the live tool I run on Claude, help you capture and challenge risks, and can add or change them. This demo has no AI, so I only give a fixed reply.");
    }
    document.getElementById('rmBotText')?.focus();
  }
}

const BOT_MINI_AVATAR = '<svg viewBox="0 0 32 32" width="14" height="14" aria-hidden="true"><circle cx="16" cy="15" r="9" fill="none" stroke="currentColor" stroke-width="2"/><path d="M9.5 25.5h13" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M25.8 7.2l1-2.4 1 2.4 2.4 1-2.4 1-1 2.4-1-2.4-2.4-1z" fill="currentColor"/></svg>';

// Mini-Markdown fuer Bot-Antworten: erst alles escapen, dann nur Absaetze,
// Listen, **fett** und `code` aufbauen. Kein rohes HTML aus dem Modell.
function renderBotMarkdown(text) {
  const inline = s => s
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');
  let html = '';
  let list = null; // 'ul' | 'ol'
  const closeList = () => { if (list) { html += `</${list}>`; list = null; } };
  for (const raw of esc(text).split('\n')) {
    const line = raw.trim();
    const ul = /^[-•*]\s+(.*)/.exec(line);
    const ol = /^\d+[.)]\s+(.*)/.exec(line);
    const head = /^#{1,4}\s+(.*)/.exec(line);
    if (ul) {
      if (list !== 'ul') { closeList(); html += '<ul>'; list = 'ul'; }
      html += `<li>${inline(ul[1])}</li>`;
    } else if (ol) {
      if (list !== 'ol') { closeList(); html += '<ol>'; list = 'ol'; }
      html += `<li>${inline(ol[1])}</li>`;
    } else if (head) {
      closeList();
      html += `<p><strong>${inline(head[1])}</strong></p>`;
    } else if (!line) {
      closeList();
    } else {
      closeList();
      html += `<p>${inline(line)}</p>`;
    }
  }
  closeList();
  return html || '<p></p>';
}

function appendBotMsg(who, text) {
  const msgs = document.getElementById('rmBotMsgs');
  if (!msgs) return null;
  const el = document.createElement('div');
  el.className = `rm-bot-msg rm-bot-msg-${who}`;
  if (who === 'bot') el.innerHTML = renderBotMarkdown(text);
  else el.textContent = text;
  if (who === 'bot') {
    const row = document.createElement('div');
    row.className = 'rm-bot-row';
    const avatar = document.createElement('span');
    avatar.className = 'rm-bot-mini';
    avatar.setAttribute('aria-hidden', 'true');
    avatar.innerHTML = BOT_MINI_AVATAR;
    row.appendChild(avatar);
    row.appendChild(el);
    msgs.appendChild(row);
  } else {
    msgs.appendChild(el);
  }
  msgs.scrollTop = msgs.scrollHeight;
  return el;
}

async function sendBotMessage() {
  if (botBusy || !register || !session) return;
  const input = document.getElementById('rmBotText');
  const text = (input?.value || '').trim();
  if (!text) return;
  input.value = '';
  appendBotMsg('user', text);
  const pending = appendBotMsg('bot', '…');
  botBusy = true;
  const sendBtn = document.getElementById('rmBotSend');
  if (sendBtn) sendBtn.disabled = true;
  try {
    const data = await askRiskBot(register.id, text, botHistory);
    botHistory = data.history || [];
    if (pending) pending.innerHTML = renderBotMarkdown(data.reply || '(no answer)');
  } catch (e) {
    if (pending) pending.textContent = `Error: ${e.message || 'bot unavailable'}`;
  } finally {
    botBusy = false;
    if (sendBtn) sendBtn.disabled = false;
    const msgs = document.getElementById('rmBotMsgs');
    if (msgs) msgs.scrollTop = msgs.scrollHeight;
  }
}

// ── Register view (KPIs, matrix, table) ─────────────────────────────────────

function matrixCellClass(l, i) {
  return `po-risk-cell po-risk-cell-${riskLevel(riskScore(l, i))}`;
}

function riskTh(key, label, filterKey, extraClass) {
  const active = riskSort.key === key;
  const fActive = filterKey && tableFilter[filterKey].size;
  const filterBtn = filterKey
    ? `<button type="button" class="rm-th-filter${fActive ? ' active' : ''}" title="Filter" aria-label="Filter ${esc(label)}" onclick="event.stopPropagation();openColFilter('${filterKey}', this)">▾</button>`
    : '';
  return `<th class="rm-th${active ? ' active' : ''}${extraClass ? ' ' + extraClass : ''}">` +
    `<span class="rm-th-inner" onclick="sortBy('${key}')">${esc(label)}</span>${filterBtn}` +
    `</th>`;
}

function renderRegister() {
  const all = allRisksFlat();
  const matrixAll = all.filter(riskMatchesFilters);

  // Apply matrix cell filter
  let rows = matrixAll;
  if (riskMatrixFilter.l != null) {
    rows = rows.filter(r => r.likelihood === riskMatrixFilter.l && r.impact === riskMatrixFilter.i);
  }
  rows = sortRows(rows);

  const resetBtn = document.getElementById('rmResetFilters');
  if (resetBtn) resetBtn.hidden = !anyRiskFilterActive();

  // KPIs
  const critical = matrixAll.filter(r => riskLevel(riskScore(r.likelihood, r.impact)) === 'critical' && r.status !== 'closed').length;
  const high = matrixAll.filter(r => riskLevel(riskScore(r.likelihood, r.impact)) === 'high' && r.status !== 'closed').length;
  const open = matrixAll.filter(r => r.status !== 'closed').length;
  const overdue = matrixAll.filter(r => r.isOverdueReview).length;

  document.getElementById('riskSummary').innerHTML = `
    <div class="report-kpi"><span class="report-kpi-val">${matrixAll.length}</span><span class="report-kpi-lbl">Total risks</span></div>
    <div class="report-kpi"><span class="report-kpi-val warn">${critical}</span><span class="report-kpi-lbl">Critical</span></div>
    <div class="report-kpi"><span class="report-kpi-val warn">${high}</span><span class="report-kpi-lbl">High</span></div>
    <div class="report-kpi"><span class="report-kpi-val">${open}</span><span class="report-kpi-lbl">Active</span></div>
    ${overdue ? `<div class="report-kpi"><span class="report-kpi-val warn">${overdue}</span><span class="report-kpi-lbl">Review overdue</span></div>` : ''}`;

  // Heat map
  let matrixHtml = '<div class="po-risk-matrix-corner"></div>';
  for (let i = 1; i <= 5; i++) {
    matrixHtml += `<div class="po-risk-matrix-axis-x">${IMPACT_SCALE[i - 1].l.split('·')[1]?.trim() || i}</div>`;
  }
  for (let l = 5; l >= 1; l--) {
    matrixHtml += `<div class="po-risk-matrix-axis-y-label">${LIKELIHOOD_SCALE[l - 1].l.split('·')[1]?.trim() || l}</div>`;
    for (let i = 1; i <= 5; i++) {
      const cellRisks = matrixAll.filter(r => r.likelihood === l && r.impact === i);
      const active = riskMatrixFilter.l === l && riskMatrixFilter.i === i;
      matrixHtml += `<div class="${matrixCellClass(l, i)}${active ? ' selected' : ''}" onclick="filterRiskMatrix(${l},${i})" title="Likelihood ${l} × Impact ${i} = ${riskScore(l, i)}">
        <span class="po-risk-cell-score">${riskScore(l, i)}</span>
        <div class="po-risk-cell-chips">${cellRisks.map(r =>
          `<button type="button" class="po-risk-chip risk-level-${riskLevel(riskScore(r.likelihood, r.impact))}" onclick="event.stopPropagation();openRiskModal(${esc(JSON.stringify(r.areaUuid))}, ${esc(JSON.stringify(r.uuid))})" title="${esc(r.title)}">${esc(r.id)}</button>`
        ).join('')}</div>
      </div>`;
    }
  }
  matrixHtml += '<div class="po-risk-matrix-legend">Impact →</div>';
  document.getElementById('riskMatrix').innerHTML = matrixHtml;

  // Table
  const body = document.getElementById('risksTabBody');
  const header = `<thead><tr>
      ${riskTh('id', 'ID', 'id')}
      ${riskTh('area', 'Area', 'area', 'rm-col-sm')}
      ${riskTh('title', 'Title', 'title')}
      ${riskTh('recorded', 'Recorded', 'recorded', 'rm-col-md')}
      ${riskTh('by', 'By', 'by', 'rm-col-md')}
      ${riskTh('score', 'Score', 'score')}
      ${riskTh('strategy', 'Strategy', 'strategy', 'rm-col-md')}
      ${riskTh('owner', 'Owner', 'owner', 'rm-col-sm')}
      ${riskTh('status', 'Status', 'status')}
    </tr></thead>`;

  const tbody = rows.length
    ? rows.map(r => {
        const score = riskScore(r.likelihood, r.impact);
        const level = riskLevel(score);
        const args = `${esc(JSON.stringify(r.areaUuid))}, ${esc(JSON.stringify(r.uuid))}`;
        return `<tr onclick="openRiskModal(${args})" title="Edit ${esc(r.id)}"${r.isOverdueReview ? ' class="rm-row-overdue"' : ''}>
        <td class="po-id">${esc(r.id)}</td>
        <td class="rm-col-sm"><span class="po-id">${esc(r.areaId)}</span> ${esc(r.areaTitle)}</td>
        <td>${esc(r.title)}</td>
        <td class="rm-col-md" title="Recorded on ${esc(fmtD(r.recordedAt))}">${fmtD(r.recordedAt)}</td>
        <td class="rm-col-md">${r.recordedBy ? chip(r.recordedBy) : ''}</td>
        <td>${score ? `<span class="risk-level risk-level-${level}">${score}</span>` : ''}</td>
        <td class="rm-col-md">${strategyLabel(r.strategy)}</td>
        <td class="rm-col-sm">${r.owner ? chip(r.owner) : ''}</td>
        <td>
          <span class="risk-status risk-status-${esc(r.status)}">${esc(riskStatusLabel(r.status))}</span>
          ${r.isOverdueReview ? `<span class="rm-overdue-badge" title="Review due ${esc(fmtD(r.reviewDue))}">Review due</span>` : ''}
        </td>
      </tr>`;
      }).join('')
    : '<tr class="rm-empty-row"><td colspan="9">No risks match. Adjust filters or add a risk.</td></tr>';

  body.innerHTML = `<table class="po-actions-table po-risks-table">${header}<tbody>${tbody}</tbody></table>`;

  // Max. 6 Zeilen sichtbar, darueber wird die Tabelle scrollbar. Hoehe nach
  // dem Rendern messen, weil Zeilen je nach Umbruch unterschiedlich hoch sind.
  if (rows.length > 6) {
    const thead = body.querySelector('thead');
    const trs = [...body.querySelectorAll('tbody tr')].slice(0, 6);
    const h = (thead?.offsetHeight || 0) + trs.reduce((sum, tr) => sum + tr.offsetHeight, 0);
    body.style.maxHeight = h + 'px';
    body.style.overflowY = 'auto';
  } else {
    body.style.maxHeight = '';
    body.style.overflowY = '';
  }
}

function exportPDF() {
  const all = allRisksFlat();
  if (!all.length) { alert('No risks to export.'); return; }

  const title = register?.title || 'Risk Register';
  const now = fmtDate(new Date());
  const critical = all.filter(r => riskLevel(riskScore(r.likelihood, r.impact)) === 'critical' && r.status !== 'closed').length;
  const high = all.filter(r => riskLevel(riskScore(r.likelihood, r.impact)) === 'high' && r.status !== 'closed').length;
  const open = all.filter(r => r.status !== 'closed').length;
  const overdue = all.filter(r => r.isOverdueReview).length;

  const levelStyle = {
    critical: 'background:#fee2e2;color:#991b1b',
    high: 'background:#ffedd5;color:#9a3412',
    medium: 'background:#fef9c3;color:#854d0e',
    low: 'background:#f0fdf4;color:#166534',
  };
  const cellBg = { critical: '#fee2e2', high: '#ffedd5', medium: '#fef9c3', low: '#f0fdf4' };

  // Heat map
  let matrixHtml = `<table style="border-collapse:collapse;font-size:0.72rem">
    <tr><td></td>${[1,2,3,4,5].map(i => `<th style="text-align:center;padding:3px 10px;color:#6b7280;font-weight:500">${IMPACT_SCALE[i-1].l.split('·')[1]?.trim() || i}</th>`).join('')}</tr>`;
  for (let l = 5; l >= 1; l--) {
    matrixHtml += `<tr><th style="text-align:right;padding:3px 8px;color:#6b7280;font-weight:500;white-space:nowrap">${LIKELIHOOD_SCALE[l-1].l.split('·')[1]?.trim() || l}</th>`;
    for (let i = 1; i <= 5; i++) {
      const sc = riskScore(l, i);
      const lv = riskLevel(sc);
      const cellRisks = all.filter(r => r.likelihood === l && r.impact === i);
      matrixHtml += `<td style="width:76px;height:52px;background:${cellBg[lv]};border:1px solid #e5e7eb;vertical-align:top;padding:4px">
        <div style="color:#9ca3af;font-size:0.6rem;margin-bottom:2px">${sc}</div>
        ${cellRisks.map(r => `<div style="font-size:0.62rem;font-weight:600;color:#374151">${esc(r.id)}</div>`).join('')}
      </td>`;
    }
    matrixHtml += '</tr>';
  }
  matrixHtml += '</table>';

  // Summary table
  const tableHtml = `<table style="width:100%;border-collapse:collapse;font-size:0.76rem">
    <thead><tr style="background:#f3f4f6;border-bottom:2px solid #e5e7eb">
      <th style="padding:6px 8px;text-align:left">ID</th>
      <th style="padding:6px 8px;text-align:left">Area</th>
      <th style="padding:6px 8px;text-align:left">Title</th>
      <th style="padding:6px 8px;text-align:left">Score</th>
      <th style="padding:6px 8px;text-align:left">Strategy</th>
      <th style="padding:6px 8px;text-align:left">Owner</th>
      <th style="padding:6px 8px;text-align:left">Status</th>
      <th style="padding:6px 8px;text-align:left">Review due</th>
    </tr></thead>
    <tbody>${all.map((r, idx) => {
      const sc = riskScore(r.likelihood, r.impact);
      const lv = riskLevel(sc);
      return `<tr style="background:${idx % 2 ? '#f9fafb' : '#fff'};border-bottom:1px solid #e5e7eb">
        <td style="padding:5px 8px;font-family:monospace;font-size:0.68rem">${esc(r.id)}</td>
        <td style="padding:5px 8px">${esc(r.areaId)}</td>
        <td style="padding:5px 8px;font-weight:500">${esc(r.title)}</td>
        <td style="padding:5px 8px">${sc ? `<span style="display:inline-block;padding:2px 6px;border-radius:4px;font-size:0.68rem;font-weight:700;${levelStyle[lv]}">${sc}</span>` : ''}</td>
        <td style="padding:5px 8px">${strategyLabel(r.strategy)}</td>
        <td style="padding:5px 8px">${esc(r.owner) || ''}</td>
        <td style="padding:5px 8px">${riskStatusLabel(r.status)}${r.isOverdueReview ? ' <b style="color:#dc2626"> (!)</b>' : ''}</td>
        <td style="padding:5px 8px${r.isOverdueReview ? ';color:#dc2626;font-weight:600' : ''}">${fmtD(r.reviewDue) || ''}</td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;

  // Detail cards
  const field = (label, val) => val
    ? `<tr><td style="padding:3px 0;color:#6b7280;width:150px;vertical-align:top;font-size:0.75rem">${label}</td><td style="padding:3px 0;font-size:0.75rem">${esc(val)}</td></tr>`
    : '';

  const detailsHtml = all.map(r => {
    const sc = riskScore(r.likelihood, r.impact);
    const lv = riskLevel(sc);
    const resSc = r.residualScore;
    const resLv = resSc ? riskLevel(resSc) : null;
    return `<div style="border:1px solid #e5e7eb;border-radius:8px;padding:16px;margin:10px 0;break-inside:avoid">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:10px">
        <div>
          <span style="font-family:monospace;font-size:0.68rem;color:#9ca3af">${esc(r.id)}</span>
          <div style="font-size:0.95rem;font-weight:600;margin:2px 0">${esc(r.title)}</div>
          <div style="font-size:0.72rem;color:#6b7280">${esc(r.areaId)} · ${esc(r.areaTitle)}</div>
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end">
          ${sc ? `<span style="padding:3px 8px;border-radius:4px;font-size:0.7rem;font-weight:700;${levelStyle[lv]}">${sc} · ${riskLevelLabel(lv)}</span>` : ''}
          ${resSc ? `<span style="padding:3px 8px;border-radius:4px;font-size:0.7rem;font-weight:700;${levelStyle[resLv]}">Residual: ${resSc} · ${riskLevelLabel(resLv)}</span>` : ''}
        </div>
      </div>
      <table style="width:100%;border-collapse:collapse">
        ${field('Risk event', r.description)}
        ${field('Cause / trigger', r.cause)}
        ${field('Impact if occurs', r.consequence)}
        ${field('Mitigation', r.mitigation)}
        ${field('Mitigation owner', r.mitigationOwner)}
        ${r.mitigationDue ? field('Mitigation due', fmtD(r.mitigationDue)) : ''}
        ${field('Contingency plan', r.contingency)}
        ${field('Early warning signs', r.triggers)}
        <tr><td style="padding:3px 0;color:#6b7280;width:150px;font-size:0.75rem">Status</td>
            <td style="padding:3px 0;font-size:0.75rem"><b>${riskStatusLabel(r.status)}</b>${r.owner ? ` · Owner: ${esc(r.owner)}` : ''}</td></tr>
        ${r.reviewDue ? `<tr><td style="padding:3px 0;color:#6b7280;width:150px;font-size:0.75rem">Next review</td>
            <td style="padding:3px 0;font-size:0.75rem${r.isOverdueReview ? ';color:#dc2626;font-weight:600' : ''}">${fmtD(r.reviewDue)}${r.isOverdueReview ? ' · OVERDUE' : ''}</td></tr>` : ''}
        ${r.recordedAt ? `<tr><td style="padding:3px 0;color:#6b7280;width:150px;font-size:0.75rem">Recorded</td>
            <td style="padding:3px 0;font-size:0.75rem">${fmtD(r.recordedAt)}${r.recordedBy ? ` by ${esc(r.recordedBy)}` : ''}</td></tr>` : ''}
      </table>
    </div>`;
  }).join('');

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${esc(title)} · Risk Register</title>
<style>
  *{box-sizing:border-box}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;margin:0;padding:28px 36px;color:#111827;background:#fff;line-height:1.5}
  h1{font-size:1.55rem;font-weight:700;margin:0 0 3px}
  h2{font-size:1rem;font-weight:600;margin:28px 0 10px;border-bottom:1px solid #e5e7eb;padding-bottom:4px;color:#111827}
  .meta{font-size:0.78rem;color:#6b7280;margin:0 0 18px}
  .kpis{display:flex;gap:12px;margin:16px 0;flex-wrap:wrap}
  .kpi{background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:10px 16px}
  .kv{display:block;font-size:1.4rem;font-weight:700;color:#111827}
  .kv.warn{color:#dc2626}
  .kl{font-size:0.7rem;color:#6b7280}
  .print-btn{position:fixed;top:16px;right:16px;padding:8px 18px;background:#111827;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:0.85rem;font-weight:500;z-index:100;box-shadow:0 2px 8px rgba(0,0,0,.2)}
  @media print{
    .print-btn{display:none}
    body{padding:6mm 8mm}
    h2{break-before:auto}
    .detail-section{break-before:page}
    @page{margin:10mm;size:A4}
  }
</style>
</head>
<body>
<button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
<h1>${esc(title)}</h1>
<p class="meta">Exported ${now} · ${all.length} risk${all.length === 1 ? '' : 's'}</p>
<div class="kpis">
  <div class="kpi"><span class="kv">${all.length}</span><span class="kl">Total risks</span></div>
  <div class="kpi"><span class="kv warn">${critical}</span><span class="kl">Critical</span></div>
  <div class="kpi"><span class="kv warn">${high}</span><span class="kl">High</span></div>
  <div class="kpi"><span class="kv">${open}</span><span class="kl">Active</span></div>
  ${overdue ? `<div class="kpi"><span class="kv warn">${overdue}</span><span class="kl">Review overdue</span></div>` : ''}
</div>
<h2>Risk heat map (inherent)</h2>
${matrixHtml}
<h2>Risk register</h2>
${tableHtml}
<div class="detail-section">
<h2>Risk details</h2>
${detailsHtml}
</div>
</body>
</html>`;

  const w = window.open('', '_blank');
  if (!w) { alert('Allow pop-ups for this page to use Export PDF.'); return; }
  w.document.write(html);
  w.document.close();
}

function modalBgClick(e, id) {
  if (e.target.id === id) {
    if (id === 'riskModalBg') closeRiskModal();
    else if (id === 'areaModalBg') closeAreaModal();
    else if (id === 'syncModalBg') closeSyncModal();
    else if (id === 'membersModalBg') closeMembersModal();
    else if (id === 'passwordSetupBg') closePasswordSetupModal();
  }
}

function initDatePickers() {
  document.querySelectorAll('input[type="date"]').forEach(el => {
    if (el.dataset.rmDateInit) return;
    el.dataset.rmDateInit = '1';
    const closePicker = () => setTimeout(() => el.blur(), 0);
    el.addEventListener('change', closePicker);
    el.addEventListener('input', closePicker);
  });
}

// ── Sync status + account modal ─────────────────────────────────────────────

function setSyncStatus(cls, text) {
  currentSyncStatus = cls;
  const modalDot = document.getElementById('syncDotModal');
  if (modalDot) modalDot.className = 'sync-dot ' + cls;
  const t = document.getElementById('syncStatusText');
  if (t) t.textContent = text || '';
}

function updateSyncModalUI() {
  const loggedIn = !!session;
  showEl('syncAuthPanel', !loggedIn);
  showEl('syncLoggedIn', loggedIn);
  if (loggedIn) {
    document.getElementById('syncUserLabel').textContent = currentUserName() || session.user.email || 'User';
  }
  updateMenuUI();
}

function openSyncModal() {
  updateSyncModalUI();
  document.getElementById('syncModalBg').classList.add('open');
}

function closeSyncModal() {
  document.getElementById('syncModalBg').classList.remove('open');
}

function openPasswordSetupModal(type) {
  const bg = document.getElementById('passwordSetupBg');
  const intro = document.getElementById('passwordSetupIntro');
  if (intro) {
    intro.textContent = type === 'recovery'
      ? 'Choose a new password for your account.'
      : 'You were invited to a specific register. Choose a password so you can sign in. You only get access to registers you are invited to.';
  }
  bg?.classList.add('open');
  const nameEl = document.getElementById('setupName');
  if (nameEl && !nameEl.value) nameEl.value = currentUserName();
  document.getElementById('setupPassword')?.focus();
}

function closePasswordSetupModal() {
  document.getElementById('passwordSetupBg')?.classList.remove('open');
  document.getElementById('setupPassword').value = '';
  document.getElementById('setupPasswordConfirm').value = '';
}

function maybeRequirePasswordSetup(type) {
  if (!session || !type) return false;
  clearAuthCallbackUrl();
  pendingAuthLinkType = null;
  openPasswordSetupModal(type);
  return true;
}

async function submitPasswordSetup() {
  const pw = document.getElementById('setupPassword').value;
  const confirm = document.getElementById('setupPasswordConfirm').value;
  const name = document.getElementById('setupName')?.value.trim() || '';
  if (!name) { alert('Please enter your name. It is shown as owner in the register.'); return; }
  if (pw.length < 8) { alert('Password must be at least 8 characters.'); return; }
  if (pw !== confirm) { alert('Passwords do not match.'); return; }
  try {
    if (pendingTokenHash) {
      // Einmal-Token aus dem Mail-Link jetzt einloesen — erst das gibt die Session.
      session = await verifyTokenHash(pendingTokenHash.tokenHash, pendingTokenHash.type);
      pendingTokenHash = null;
      clearAuthCallbackUrl();
    }
    await updatePassword(pw);
    await saveDisplayName(name);
    await refreshProfiles();
    closePasswordSetupModal();
    closeSyncModal();
    if (!register) await bootstrapData();
    else updateSyncModalUI();
    setSyncStatus('ok', `Demo · ${risks.length} risk(s)`);
  } catch (e) {
    alert(e.message || 'Could not save password');
  }
}

async function submitPasswordReset() {
  const email = document.getElementById('syncLoginEmail').value.trim();
  if (!email) { alert('Enter your email above first, then click "Forgot password?" again.'); return; }
  try {
    await requestPasswordReset(email);
    alert('Password reset email sent. Open the link in it to choose a new password.');
  } catch (e) {
    alert(e.message || 'Could not send reset email');
  }
}

async function submitSyncLogin() {
  const email = document.getElementById('syncLoginEmail').value.trim();
  const password = document.getElementById('syncLoginPassword').value;
  if (!email || !password) { alert('Email and password required.'); return; }
  try {
    const data = await signIn(email, password);
    session = data.session;
    document.getElementById('syncLoginPassword').value = '';
    closeSyncModal();
    await bootstrapData();
  } catch (e) {
    const msg = e.message || 'Login failed';
    alert(/signups not allowed|signup is disabled|user already registered/i.test(msg)
      ? 'This tool is invite-only. Ask the register owner to send you an email invitation to their register.'
      : msg);
  }
}

async function submitSyncLogout() {
  try { await signOut(); } catch (_) {}
  session = null;
  unsubscribe();
  register = null;
  registers = [];
  areas = [];
  risks = [];
  members = [];
  profiles = new Map();
  myProfile = null;
  applyRegisterToUI();
  refreshAll();
  setSyncStatus('off', 'Not signed in');
  updateSyncModalUI();
}

// ── Members / admin modal ───────────────────────────────────────────────────

function roleLabel(role) {
  return { owner: 'Owner', editor: 'Editor', viewer: 'Viewer' }[role] || role;
}

function renderMembersList() {
  const list = document.getElementById('membersList');
  if (!list) return;
  const meId = session?.user?.id;
  const order = { owner: 0, editor: 1, viewer: 2 };
  const rows = [...members].sort((a, b) =>
    (order[a.role] ?? 9) - (order[b.role] ?? 9) || userName(a.user_id).localeCompare(userName(b.user_id)));
  list.innerHTML = rows.length
    ? rows.map(m => {
        const p = profiles.get(m.user_id);
        const name = p?.display_name || nameFromEmail(p?.email) || 'Unknown';
        const email = p?.email || '';
        const isMe = m.user_id === meId;
        const manageable = isOwner() && !isMe && m.role !== 'owner';
        const controls = manageable
          ? `<select class="rm-member-role" onchange="changeMemberRole(${esc(JSON.stringify(m.user_id))}, this.value)" title="Change role">
              <option value="editor"${m.role === 'editor' ? ' selected' : ''}>Editor</option>
              <option value="viewer"${m.role === 'viewer' ? ' selected' : ''}>Viewer</option>
            </select>
            <button type="button" class="btn btn-secondary btn-sm po-danger" onclick="removeMemberClick(${esc(JSON.stringify(m.user_id))})" title="Remove from this register">Remove</button>`
          : `<span class="rm-member-rolelabel rm-member-role-${esc(m.role)}">${esc(roleLabel(m.role))}</span>`;
        return `<div class="rm-member-row">
          <div class="rm-member-id">
            <span class="rm-member-name">${chip(name)}${isMe ? '<span class="rm-member-you">you</span>' : ''}</span>
            <span class="rm-member-email">${esc(email)}</span>
          </div>
          <div class="rm-member-actions">${controls}</div>
        </div>`;
      }).join('')
    : '<p class="rm-menu-empty">No members loaded.</p>';
}

async function openMembersModal() {
  if (!register || !session) return;
  const label = document.getElementById('membersRegisterLabel');
  if (label) label.textContent = register.title || '';
  showEl('membersInvite', isOwner());
  showEl('membersDangerZone', isOwner());
  renderMembersList();
  document.getElementById('membersModalBg').classList.add('open');
  try {
    members = await listMembers(register.id);
    await refreshProfiles();
    renderMembersList();
  } catch (_) {}
}

function closeMembersModal() {
  document.getElementById('membersModalBg').classList.remove('open');
}

async function changeMemberRole(userId, role) {
  if (!register || !isOwner()) return;
  try {
    await updateMemberRole(register.id, userId, role);
    const m = members.find(x => x.user_id === userId);
    if (m) m.role = role;
    setSyncStatus('ok', 'Saved');
  } catch (e) {
    alert(e.message || 'Could not change role');
  }
  renderMembersList();
}

async function removeMemberClick(userId) {
  if (!register || !isOwner()) return;
  const name = userName(userId) || 'this member';
  if (!confirm(`Remove ${name} from "${register.title}"? They lose access to this register only.`)) return;
  try {
    await removeMember(register.id, userId);
    members = members.filter(m => m.user_id !== userId);
    setSyncStatus('ok', 'Removed');
  } catch (e) {
    alert(e.message || 'Could not remove member');
  }
  renderMembersList();
}

async function addSyncMember() {
  const email = document.getElementById('syncMemberEmail').value.trim();
  const name = document.getElementById('syncMemberName')?.value.trim() || '';
  if (!email || !register) return;
  if (!isOwner()) { alert('Only the register owner can invite members.'); return; }
  const btn = document.getElementById('syncInviteBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Inviting…'; }
  try {
    await inviteMemberByEmail(register.id, email, 'editor', name);
    document.getElementById('syncMemberEmail').value = '';
    const nameEl = document.getElementById('syncMemberName');
    if (nameEl) nameEl.value = '';
    members = await listMembers(register.id);
    await refreshProfiles();
    renderMembersList();
    alert('Added to this demo register. No email was sent. In the live tool, new users get an invitation email.');
  } catch (e) {
    alert(e.message || 'Could not invite user');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Invite'; }
  }
}

// ── Bootstrap ────────────────────────────────────────────────────────────────

let bootstrapInFlight = false;

async function bootstrapData() {
  if (bootstrapInFlight) return;
  bootstrapInFlight = true;
  try {
    await doBootstrapData();
  } finally {
    bootstrapInFlight = false;
  }
}

async function doBootstrapData() {
  setSyncStatus('syncing', 'Loading registers…');
  try {
    myProfile = await loadMyProfile(session.user.id);
    registers = dedupeRegisters(await listRegisters());
  } catch (e) {
    setSyncStatus('error', 'Could not load registers');
    alert(e.message || 'Could not load your registers');
    return;
  }

  if (!registers.length) {
    if (!canCreateRegisters()) {
      register = null;
      areas = [];
      risks = [];
      applyRegisterToUI();
      refreshAll();
      setSyncStatus('off', 'No register assigned');
      alert('You have not been invited to a register yet. Ask the register owner for access.');
      return;
    }
    try {
      const row = await createRegister('Risk Register', currentUserName());
      await Promise.all([
        createArea(row.id, 'A01', 'Project delivery', 1),
        createArea(row.id, 'A02', 'External dependencies', 2),
      ]);
      registers = dedupeRegisters(await listRegisters());
    } catch (e) {
      setSyncStatus('error', 'Could not create register');
      alert(e.message || 'Could not create your first register');
      return;
    }
  }

  let activeId = null;
  const urlProject = new URLSearchParams(location.search).get('project');
  if (urlProject && registers.some(r => r.id === urlProject)) activeId = urlProject;
  if (!activeId) {
    try {
      const remembered = localStorage.getItem(LAST_REGISTER_KEY);
      if (remembered && registers.some(r => r.id === remembered)) activeId = remembered;
    } catch (_) {}
  }
  if (!activeId) activeId = registers[0].id;

  register = registers.find(r => r.id === activeId);
  try { localStorage.setItem(LAST_REGISTER_KEY, register.id); } catch (_) {}
  await loadActiveRegister();
  updateSyncModalUI();
}

async function initApp() {
  pendingAuthLinkType = getAuthLinkType();
  pendingTokenHash = getAuthTokenHash();
  const authError = getAuthErrorFromUrl();
  session = await getSession();

  if (pendingTokenHash) {
    // Mail-Link mit token_hash: erst beim Speichern einloesen (verifyTokenHash),
    // damit Mail-Scanner das Einmal-Token nicht entwerten koennen.
    if (session) await bootstrapData();
    else {
      applyRegisterToUI();
      refreshAll();
      setSyncStatus('off', 'Not signed in');
    }
    openPasswordSetupModal(pendingTokenHash.type);
    return;
  }

  if (authError) {
    clearAuthCallbackUrl();
    alert('This password link is invalid or was already used. Some email programs pre-open links. Request a fresh one with "Forgot password?".');
  }

  if (!session) {
    applyRegisterToUI();
    refreshAll();
    setSyncStatus('off', 'Not signed in');
    openSyncModal();
    return;
  }
  await bootstrapData();
  if (pendingAuthLinkType) maybeRequirePasswordSetup(pendingAuthLinkType);
}

onAuthChange((event, newSession) => {
  const hadSession = !!session;
  session = newSession;
  if (!hadSession && newSession) {
    if (pendingAuthLinkType) {
      maybeRequirePasswordSetup(pendingAuthLinkType);
    } else if (event === 'PASSWORD_RECOVERY') {
      maybeRequirePasswordSetup('recovery');
    } else if (!register && !bootstrapInFlight) {
      // Login kam ueber ein Auth-Event (z. B. anderer Tab) — Daten nachladen,
      // sonst bleibt die Ansicht trotz Session leer.
      bootstrapData();
    }
  }
  if (hadSession && !newSession) {
    unsubscribe();
    register = null;
    registers = [];
    areas = [];
    risks = [];
    myProfile = null;
    applyRegisterToUI();
    refreshAll();
    setSyncStatus('off', 'Session expired. Please log in');
    openSyncModal();
    updateSyncModalUI();
  }
});

